def _norm(cells):
    if not cells:
        return frozenset()
    mr = min(r for r, c in cells)
    mc = min(c for r, c in cells)
    return frozenset((r-mr, c-mc) for r, c in cells)

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify colored shape components in the right-hand panel.
    unseen = {(r, c) for r in range(h) for c in range(5, w) if grid[r][c] != 0}
    objects = []
    while unseen:
        start = unseen.pop()
        color = grid[start[0]][start[1]]
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen and grid[p[0]][p[1]] == color:
                    unseen.remove(p)
                    comp.add(p)
                    stack.append(p)
        objects.append((color, _norm(comp)))
    # Each enclosed zero-pattern band on the left is a shape slot.
    bands = []
    r = 0
    while r < h:
        if all(grid[r][c] == 8 for c in range(5)):
            r += 1
            continue
        start = r
        while r < h and not all(grid[r][c] == 8 for c in range(5)):
            r += 1
        cells = {(rr-start, c) for rr in range(start, r) for c in range(5) if grid[rr][c] == 0}
        bands.append((start, r, _norm(cells)))
    out = [row[:5] for row in grid]
    for start, end, shape in bands:
        color = next((color for color, objshape in objects if objshape == shape), None)
        if color is None:
            raise ValueError('no matching colored shape for left slot')
        for rr in range(start, end):
            for c in range(5):
                if out[rr][c] == 0:
                    out[rr][c] = color
    return out
